questionvariables.text:
/* Design: classify pattern: true or false in a fixed order; option values are unique per dropdown. Each variant uses a curated set drawn from a pool. Source: original. */
keys: [1,0,1,0,1,0,1,1,0,1,0,1];
sets: [[1,2,5,9,11],[3,4,6,8,12],[7,9,2,10,4],[5,6,11,12,1],[8,2,3,9,6],[10,11,4,7,1],[12,6,9,3,5],[2,4,8,11,10],[9,1,6,12,7],[11,3,5,2,8]];
ix: 1+rand(10);
S: random_permutation(sets[ix]);
kk: makelist(keys[S[k]], k, 1, 5);
it1: S[1];
opt1: [[11, is(kk[1]=1), "true"], [12, is(kk[1]=0), "false"]];
ta1: if kk[1]=1 then 11 else 12;
wr1: if kk[1]=1 then 12 else 11;
it2: S[2];
opt2: [[21, is(kk[2]=1), "true"], [22, is(kk[2]=0), "false"]];
ta2: if kk[2]=1 then 21 else 22;
wr2: if kk[2]=1 then 22 else 21;
it3: S[3];
opt3: [[31, is(kk[3]=1), "true"], [32, is(kk[3]=0), "false"]];
ta3: if kk[3]=1 then 31 else 32;
wr3: if kk[3]=1 then 32 else 31;
it4: S[4];
opt4: [[41, is(kk[4]=1), "true"], [42, is(kk[4]=0), "false"]];
ta4: if kk[4]=1 then 41 else 42;
wr4: if kk[4]=1 then 42 else 41;
it5: S[5];
opt5: [[51, is(kk[5]=1), "true"], [52, is(kk[5]=0), "false"]];
ta5: if kk[5]=1 then 51 else 52;
wr5: if kk[5]=1 then 52 else 51;
